let qnets = { ai1: null, ai2: null };

class QNetSync {
    constructor(weights) {
        this.w = weights;
        this._convertWeightsToFloat32();
    }

    static async loadFromJSON(url) {
        const res = await fetch(url);
        const weights = await res.json();
        return new QNetSync(weights);
    }

    _convertWeightsToFloat32() {
        for (const key of Object.keys(this.w)) {
            const tensor = this.w[key];
            if (Array.isArray(tensor[0])) {
                this.w[key] = this._deepConvertArray(tensor);
            } else {
                this.w[key] = Float32Array.from(tensor);
            }
        }
    }

    _deepConvertArray(arr) {
        if (!Array.isArray(arr)) return arr;
        if (!Array.isArray(arr[0])) {
            return Float32Array.from(arr);
        }
        return arr.map(sub => this._deepConvertArray(sub));
    }

    // --- Linear Layer ---
    linear(input, w, b, relu = false) {
        const outDim = w.length;
        // 입력 차원이 가중치 차원과 맞지 않으면 경고 (디버깅용)
        if (input.length !== w[0].length) {
            console.error(`Input dim mismatch! Expected ${w[0].length}, got ${input.length}`);
        }
        
        const inDim = w[0].length;
        const output = new Float32Array(outDim);

        for (let i = 0; i < outDim; i++) {
            let sum = b[i];
            for (let j = 0; j < inDim; j++) {
                sum += input[j] * w[i][j];
            }
            output[i] = relu ? Math.max(0, sum) : sum;
        }
        return output;
    }

    // --- Dueling Logic ---
    calculateDueling(feat, headName) {
        const val_w = this.w[`val_${headName}_w`];
        const val_b = this.w[`val_${headName}_b`];
        const v = this.linear(feat, val_w, val_b, false)[0];

        const adv_w = this.w[`adv_${headName}_w`];
        const adv_b = this.w[`adv_${headName}_b`];
        const a = this.linear(feat, adv_w, adv_b, false);

        let sum_a = 0;
        for(let i=0; i<a.length; i++) sum_a += a[i];
        const mean_a = sum_a / a.length;

        const q_values = new Float32Array(a.length);
        for(let i=0; i<a.length; i++) {
            q_values[i] = v + (a[i] - mean_a);
        }
        return q_values;
    }

    forward(norm_state) {
        // Feature Extractor
        // 입력 차원은 이제 18입니다 (coordinate 16 + dribble 2)
        let h = this.linear(norm_state, this.w["fc1_w"], this.w["fc1_b"], true);
        h = this.linear(h, this.w["fc2_w"], this.w["fc2_b"], true);
        h = this.linear(h, this.w["fc3_w"], this.w["fc3_b"], true);

        // Dueling Heads
        const q_x = this.calculateDueling(h, 'x');
        const q_y = this.calculateDueling(h, 'y');
        const q_p = this.calculateDueling(h, 'p');

        const getArgMax = (arr) => {
            let maxIdx = 0;
            let maxVal = arr[0];
            for (let i = 1; i < arr.length; i++) {
                if (arr[i] > maxVal) {
                    maxVal = arr[i];
                    maxIdx = i;
                }
            }
            return maxIdx;
        };

        const xIdx = getArgMax(q_x);
        const yIdx = getArgMax(q_y);
        const pIdx = getArgMax(q_p);

        // [x방향(-1,0,1), y방향(-1,0,1), 파워(0,1)]
        return [
            [-1, 0, 1][xIdx],
            [-1, 0, 1][yIdx],
            [0, 1][pIdx]
        ];
    }
}

// --- ★ 수정됨: 드리블 정보를 포함한 18차원 데이터 정규화 ---
// Python 코드의 make_normalized_state 로직과 100% 일치해야 함
function normalizeState(coordinate, playerstate, aiType, dribbleCounts) {
    const GROUND_HALF_WIDTH = 216.0;
    const GROUND_HEIGHT = 304.0;
    const MAX_BALL_VX = 40.0;
    const MAX_BALL_VY = 80.0;
    const MAX_PLAYER_VX = 20.0;
    const MAX_PLAYER_VY = 30.0;

    let p1x = coordinate[0], p1y = coordinate[1];
    let p2x = coordinate[2], p2y = coordinate[3];
    let bx = coordinate[4], by = coordinate[5];
    let p1vx = 0, p1vy = 0, p2vx = 0, p2vy = 0, bvx = 0, bvy = 0;

    if (coordinate.length >= 12) {
        p1vx = coordinate[6]; p1vy = coordinate[7];
        p2vx = coordinate[8]; p2vy = coordinate[9];
        bvx = coordinate[10]; bvy = coordinate[11];
    }

    const s1 = playerstate[0];
    const s2 = playerstate[1];

    // 드리블 카운트 안전장치 (undefined일 경우 0 처리)
    const d_cnt = dribbleCounts || [0, 0];
    
    // ★ 드리블 정규화 (파이썬 코드: min(1.0, count / 3.0))
    const d1 = Math.min(1.0, d_cnt[0] / 3.0);
    const d2 = Math.min(1.0, d_cnt[1] / 3.0);

    const clip_norm = (val, max_val) => {
        let res = val / max_val;
        if (res > 1.0) res = 1.0;
        if (res < -1.0) res = -1.0;
        return res;
    };

    let state = [];

    // AI1 (왼쪽 플레이어 기준)
    if (aiType === 'ai1') {
        state = [
            (bx - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH,   by / GROUND_HEIGHT,
            clip_norm(bvx, MAX_BALL_VX),                    clip_norm(bvy, MAX_BALL_VY),
            (p1x - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH,  p1y / GROUND_HEIGHT,
            clip_norm(p1vx, MAX_PLAYER_VX),                 clip_norm(p1vy, MAX_PLAYER_VY),
            (p2x - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH,  p2y / GROUND_HEIGHT,
            clip_norm(p2vx, MAX_PLAYER_VX),                 clip_norm(p2vy, MAX_PLAYER_VY),
            s1 / 4.0, s2 / 4.0, s1 / 4.0, s2 / 4.0,
            d1, d2 // ★ [16, 17] 내 드리블, 상대 드리블 추가
        ];
    } 
    // AI2 (오른쪽 플레이어 기준 - Mirroring)
    else {
        state = [
            -(bx - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH,  by / GROUND_HEIGHT,
            clip_norm(-bvx, MAX_BALL_VX),                   clip_norm(bvy, MAX_BALL_VY),
            -(p2x - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH, p2y / GROUND_HEIGHT,
            clip_norm(-p2vx, MAX_PLAYER_VX),                clip_norm(p2vy, MAX_PLAYER_VY),
            -(p1x - GROUND_HALF_WIDTH) / GROUND_HALF_WIDTH, p1y / GROUND_HEIGHT,
            clip_norm(-p1vx, MAX_PLAYER_VX),                clip_norm(p1vy, MAX_PLAYER_VY),
            s2 / 4.0, s1 / 4.0, s2 / 4.0, s1 / 4.0,
            d2, d1 // ★ [16, 17] 내 드리블(d2)이 먼저 오도록 (파이썬 로직과 동일)
        ];
    }

    return state; // 18-dim array
}

// --- 초기화 ---
export async function initAI() {
    qnets.ai1 = await QNetSync.loadFromJSON(
        "https://uzaramen108.github.io/pikachu-volleyball-ai/resources/model/pikachu_ai1.json"
    );
    qnets.ai2 = await QNetSync.loadFromJSON(
        "https://uzaramen108.github.io/pikachu-volleyball-ai/resources/model/pikachu_ai2.json"
    );
    console.log("AI initialized (18-dim input supported).");
}

// --- 예측 ---
// ★ 수정됨: dribbleCounts 인자 추가
export function predict(inputArray, playerState, aiType, dribbleCounts) {
    const net = qnets[aiType];
    if (!net) {
        return [0, 0, 0];
    }

    // 정규화 수행 (18-dim Normalized Input)
    // dribbleCounts가 없으면 내부에서 [0,0]으로 처리됨
    const normInput = normalizeState(inputArray, playerState, aiType, dribbleCounts);

    // Forward Pass
    return net.forward(normInput);
}